(7737768, 1275747, 273752, '<td valign="top">Nice use of reflections.  Sorry, it had to be at the expense of flooding.</td>', 'Nice use of reflections.  Sorry, it had to be at the expense of flooding.', '2023-02-04 21:05:38.000000', NULL, 1),
(7737769, 1275753, 273752, '<td valign="top">I like the connection line between the adult and the child.  That is always a good photo element.</td>', 'I like the connection line between the adult and the child.  That is always a good photo element.', '2023-02-04 21:07:36.000000', NULL, 1),
(7737770, 1275749, 273752, '<td valign="top">Fits the challenge and great use of lines.  Just wish it were a tad bit sharper in focus.  But that is a hard light to work with so I get it.</td>', 'Fits the challenge and great use of lines.  Just wish it were a tad bit sharper in focus.  But that is a hard light to work with so I get it.', '2023-02-04 21:08:35.000000', NULL, 1),
(7737771, 1275632, 273752, '<td valign="top">I like the colors captured of the subject.</td>', 'I like the colors captured of the subject.', '2023-02-04 21:11:53.000000', NULL, 1),
(7737772, 1275716, 273752, '<td valign="top">This has quite a bit going on here.  I am definitely looking around the entire image, which is a good thing.  Has a noir feel to it too which I am diggin.</td>', 'This has quite a bit going on here.  I am definitely looking around the entire image, which is a good thing.  Has a noir feel to it too which I am diggin.', '2023-02-04 21:13:39.000000', NULL, 1),
(7737773, 1275741, 273752, '<td valign="top">I like the contrast in colors. I also see some lines and shapes I like.</td>', 'I like the contrast in colors. I also see some lines and shapes I like.', '2023-02-04 21:14:34.000000', NULL, 1),
(7737774, 1275620, 273752, '<td valign="top">Great BW.  Gritty (not the image quality but the subject).  Just a good image.</td>', 'Great BW.  Gritty (not the image quality but the subject).  Just a good image.', '2023-02-04 21:15:37.000000', NULL, 1),
(7737775, 1275751, 273752, '<td valign="top">I like how the image is blurred in the foreground and just behind the subject of the image.  Not sure how it fits the theme, though.</td>', 'I like how the image is blurred in the foreground and just behind the subject of the image.  Not sure how it fits the theme, though.', '2023-02-04 21:16:49.000000', NULL, 1),
